import React, { useState } from 'react';
import './styles/global.css';

const App: React.FC = () => {
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState<boolean>(false);
  const [uploadSuccess, setUploadSuccess] = useState<boolean>(false);

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      setSelectedImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
      setUploadSuccess(false);
    }
  };

  const handleSendImage = () => {
    if (!selectedImage) return;
    
    setIsUploading(true);
    
    // 模拟上传过程
    setTimeout(() => {
      setIsUploading(false);
      setUploadSuccess(true);
      // 这里可以添加实际的上传逻辑
      console.log('Image uploaded:', selectedImage);
    }, 1500);
  };

  const handleReset = () => {
    setSelectedImage(null);
    setPreviewUrl(null);
    setUploadSuccess(false);
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>Medical Aesthetics Consultation</h1>
      </header>
      <main>
        <div className="upload-section">
          <h2>Upload Patient Photo</h2>
          <p className="upload-description">
            Please upload a clear photo of the patient's face for consultation
          </p>
          
          {!selectedImage ? (
            <div className="upload-area">
              <input
                type="file"
                accept="image/*"
                onChange={handleImageUpload}
                className="file-input"
                id="file-input"
              />
              <label htmlFor="file-input" className="file-label">
                <span className="upload-icon">📷</span>
                <span>Click to upload or drag and drop</span>
              </label>
            </div>
          ) : (
            <div className="preview-container">
              <img src={previewUrl || ''} alt="Preview" className="image-preview" />
              <div className="action-buttons">
                <button 
                  className="action-button send-button" 
                  onClick={handleSendImage}
                  disabled={isUploading}
                >
                  {isUploading ? 'Sending...' : 'Send for Analysis'}
                </button>
                <button 
                  className="action-button reset-button" 
                  onClick={handleReset}
                  disabled={isUploading}
                >
                  Reset
                </button>
              </div>
            </div>
          )}
          
          {uploadSuccess && (
            <div className="success-message">
              <span className="success-icon">✓</span>
              <span>Image successfully sent for analysis!</span>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;
